using System;using System.Linq;using System.IO;using UnityEngine;using AntColony.Units;
public static class Native1112Compare{public static async System.Threading.Tasks.Task<string> Run(){var p=UnityEngine.Object.FindObjectsByType<MeshyNativeMotionPlayer>(FindObjectsSortMode.None).First(x=>x.transform.position.x>70);var original=p.transform.Find("Kemono");p.enabled=false;var a=original.GetComponent<Animator>();if(a){a.Play("Idle_A",0,.3f);a.Update(0);}await System.Threading.Tasks.Task.Delay(150);var cam=Camera.main;var focus=p.transform.position+original.localPosition+Vector3.up*.8f;cam.transform.position=focus+original.forward*3+original.right*.8f;cam.transform.LookAt(focus);cam.orthographicSize=1.2f;var rt=new RenderTexture(900,900,24);var tex=new Texture2D(900,900,TextureFormat.RGB24,false);var old=cam.targetTexture;var ar=RenderTexture.active;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,900,900),0,0);tex.Apply();File.WriteAllBytes("work/animation-1112/legacy-appearance.png",tex.EncodeToPNG());}finally{cam.targetTexture=old;RenderTexture.active=ar;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}return "legacy comparison";}}
